using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

[TestClass]
public sealed class EvalTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;
    private static ReportingConfiguration _reportingConfiguration = null!;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        var app = await _appHost.BuildAsync();
        await app.StartAsync();

        _chatClient = app.Services.GetRequiredService<IChatClient>();

        // Configure evaluation with coherence and relevance metrics
        _reportingConfiguration = new ReportingConfiguration(
            new DiskBasedReportingStorage(Path.Combine(Directory.GetCurrentDirectory(), "eval-results")),
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatClient: _chatClient);
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (_appHost is IAsyncDisposable disposable)
            await disposable.DisposeAsync();
    }

    [TestMethod]
    public async Task Chat_ReturnsCoherentResponse()
    {
        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(nameof(Chat_ReturnsCoherentResponse));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?"),
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        foreach (var metric in scenario.GetAllMetrics())
        {
            Assert.IsFalse(metric.Diagnostics?.HasFlag(EvaluationDiagnostics.FailedEvaluation),
                $"Metric '{metric.Name}' failed evaluation.");
        }
    }

    [TestMethod]
    public async Task Chat_FollowsInstructions()
    {
        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(nameof(Chat_FollowsInstructions));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant. Always respond in exactly one sentence."),
            new(ChatRole.User, "Explain what machine learning is."),
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        foreach (var metric in scenario.GetAllMetrics())
        {
            Assert.IsFalse(metric.Diagnostics?.HasFlag(EvaluationDiagnostics.FailedEvaluation),
                $"Metric '{metric.Name}' failed evaluation.");
        }
    }

    [TestMethod]
    public async Task Chat_HandlesMultiTurnConversation()
    {
        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(nameof(Chat_HandlesMultiTurnConversation));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice."),
        };

        var response1 = await _chatClient.GetResponseAsync(messages);
        messages.Add(response1.Message);
        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));

        var response2 = await _chatClient.GetResponseAsync(messages);
        messages.Add(response2.Message);

        await scenario.EvaluateAsync(messages);

        // Verify the model remembered the name
        Assert.IsTrue(
            response2.Message.Text?.Contains("Alice", StringComparison.OrdinalIgnoreCase),
            "Expected the model to remember the user's name across turns.");

        foreach (var metric in scenario.GetAllMetrics())
        {
            Assert.IsFalse(metric.Diagnostics?.HasFlag(EvaluationDiagnostics.FailedEvaluation),
                $"Metric '{metric.Name}' failed evaluation.");
        }
    }
}

